public void delete(String sessionId) {
    AgentSession session = sessions.remove(sessionId);
    SessionDocument document = runtime.sessionRepository().load(sessionId).orElseThrow(() -> notFound(sessionId));
    if (document.execution().activeRun().isPresent()) {
        throw invalid("session_delete_active");
    }
    if (session != null) session.close();
    runtime.sessionRepository().delete(sessionId, document.revision());
}

/** Releases connection-scoped resources without deleting durable Session state. */
public void detach(String sessionId) {
    sessions.remove(sessionId);

